  --faint:#8b93d6;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#34d399;
  --warn:#fbbf24;
  --bad:#fb7185;
  --border:rgba(255,255,255,.10);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
}
*{box-sizing:border-box}
.wrap{max-width:980px;margin:18px auto;padding:14px;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,"Noto Sans",sans-serif;color:var(--text)}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1b1f3a 0%, var(--bg) 55%)}
.hdr{padding:14px 14px 6px}
.hdr h1{margin:0 0 6px;font-size:22px;letter-spacing:.2px}
.sub{margin:0;color:var(--muted);line-height:1.35}
.panel{background:linear-gradient(180deg,var(--panel),var(--panel2));border:1px solid var(--border);border-radius:14px;padding:14px;margin:12px 0;box-shadow:var(--shadow)}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.row.small{margin-top:10px;align-items:flex-start}
.lbl{min-width:70px;color:var(--muted);font-weight:600}
.inp{flex:1;min-width:260px;padding:10px 12px;border-radius:12px;border:1px solid var(--border);background:rgba(255,255,255,.06);color:var(--text);font-size:16px;outline:none}
.inp:focus{border-color:rgba(125,211,252,.55);box-shadow:0 0 0 4px rgba(125,211,252,.12)}
.btn{padding:9px 12px;border-radius:12px;border:1px solid rgba(125,211,252,.35);background:rgba(125,211,252,.12);color:var(--text);cursor:pointer;font-weight:650}
.btn:hover{background:rgba(125,211,252,.18)}
.btn:active{transform:translateY(1px)}
.btn.ghost{border-color:var(--border);background:rgba(255,255,255,.06);font-weight:600}
.btn.ghost:hover{background:rgba(255,255,255,.09)}
.tog{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:8px 10px;border:1px solid var(--border);border-radius:12px;background:rgba(255,255,255,.04)}
.lbl2{color:var(--muted);font-weight:650;margin-right:4px}
.tog label{color:var(--text);font-size:14px;display:flex;gap:6px;align-items:center}
.hint{color:var(--muted);line-height:1.35}
.hint ul{margin:8px 0 0 18px;padding:0}
.hint code{color:var(--accent);font-weight:700}
.out h2{margin:0 0 10px;font-size:18px}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
@media (max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}}
@media (max-width:520px){.grid{grid-template-columns:1fr}}
.card{border:1px solid var(--border);border-radius:12px;padding:10px;background:rgba(255,255,255,.04)}
.k{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.08em}
.v{margin-top:6px;font-size:15px}
.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono","Courier New",monospace}
.play{margin-top:12px}
.playRow{display:grid;grid-template-columns:1.3fr 1fr;gap:10px}
@media (max-width:900px){.playRow{grid-template-columns:1fr}}
.playCard{border:1px solid var(--border);border-radius:12px;padding:10px;background:rgba(255,255,255,.04)}
