    if (!isVowelChar(a.ch)) continue;
    // diphthong check with next vowel
    const b = letters[i+1];
    if (b && isVowelChar(b.ch) && !b.dia && !a.dia){
      const pair = (a.ch + b.ch).toLowerCase();
      const diph = new Set(["αι","ει","οι","υι","αυ","ευ","ου","ηυ","ωυ"]);
      if (diph.has(pair)){
        count += 1;
        i += 1;
        continue;
      }
    }
    count += 1;
  }
  return Math.max(count, 1);
}

function detectEnding(word){
  const w = stripAllCombining(word).toLowerCase();
  if (w.endsWith("φις")) return "-φις";
  if (w.endsWith("χις")) return "-χις";
  if (w.endsWith("ις")) return "-ις";
  return "(other)";
}

function removeExistingAccentBreathing(word){
  // remove all combining marks; keep base letters
  return stripAllCombining(word);
}

function addAccentToVowel(word, vowelIndexFromEnd, accentType){
  // accentType: 'acute' | 'circumflex'
  // vowelIndexFromEnd: 1=last vowel nucleus, 2=penult nucleus, 3=antepenult nucleus
  const base = removeExistingAccentBreathing(word);
  const letters = Array.from(nfd(base));
  // Find vowel positions (indices in letters array) for nuclei (approx: each vowel letter counts)
  const vowelPositions = [];
  for (let i=0;i<letters.length;i++){
    const ch = letters[i];
    if (ch.match(/[\u0300-\u036f]/)) continue;
    if (isVowelChar(ch)) vowelPositions.push(i);
  }
  if (!vowelPositions.length) return base;
  const pos = vowelPositions[Math.max(0, vowelPositions.length - vowelIndexFromEnd)];
  const mark = accentType === 'circumflex' ? COMBINING.circumflex : COMBINING.acute;
  letters[pos] = letters[pos] + mark;
  return nfc(letters.join(""));
}

function suggest(word, kind, accChoice){
  const w = lastGreekWord(word);
  const norm = removeExistingAccentBreathing(w);
  const ending = detectEnding(w);
  const syll = roughSyllableCount(w);

  let note = "";
  let suggestedForm = norm;
  let label = "";

  // Auto heuristics: if ends with -ουφις or -εμφις treat as proper-ish (based on examples)
  const low = stripAllCombining(w).toLowerCase();
  const autoProper = /ουφις$/.test(low) || /εμφις$/.test(low);

  const effectiveKind = (kind === 'auto') ? (autoProper ? 'proper' : 'ethnic') : kind;

  if (ending === "-φις"){
    if (effectiveKind === 'proper'){
      suggestedForm = addAccentToVowel(norm, 3, 'acute');
      label = "proparoxytone (antepenult acute)";
      note = "Toy rule: proper names in -φις often προπαροξύνονται (e.g. Ὄνουφις, Μώμεμφις).";
    } else {
      if (syll > 2){
        suggestedForm = addAccentToVowel(norm, 1, 'acute');
        label = "oxytone (final acute)";
        note = "Toy rule: -φις with >2 syllables tends to be oxytone (ὀξύνεται).";
      } else {
        suggestedForm = addAccentToVowel(norm, 1, 'acute');
        label = "oxytone (final acute)";
        note = "Short -φις: this toy still makes it oxytone (cf. Κηφίς, Δελφίς).";
      }
    }
  } else if (ending === "-χις"){
    if (effectiveKind === 'city'){
      suggestedForm = addAccentToVowel(norm, 1, 'acute');
      label = "(place-name exception flagged)";
      note = "Herodian notes place-name exceptions for -χις; this toy keeps final acute but flags it.";
    } else {
      suggestedForm = addAccentToVowel(norm, 1, 'acute');
      label = "oxytone (final acute)";
      note = "Toy rule: -χις tends to be oxytone (ὀξύνεται).";
    }
  } else if (ending === "-ις"){
    // Feminine -is rule based on accusative
    let acc = accChoice;
    if (acc === 'auto'){
      // guess: if ends with -δις/-τις etc maybe -ιν? too hard; default to -α
      acc = '-a';
    }
    if (acc === '-a'){
      suggestedForm = addAccentToVowel(norm, 1, 'acute');
      label = "oxytone (final acute)";
      note = "If acc. is -α, Herodian: ὀξύνονται (e.g. ῥανίς).";
    } else {
      suggestedForm = addAccentToVowel(norm, 1, 'circumflex');
      label = "perispomenon (final circumflex)";
      note = "If acc. is -ιν, Herodian: περισπῶνται (e.g. Βενδῖς).";
    }
  } else {
    suggestedForm = norm;
    label = "(no rule applied)";
    note = "Try a word ending in -φις, -χις, or -ις.";
  }

  return {w, norm, ending, syll, effectiveKind, suggestedForm, label, note};
}

function makeAccusative(word, type){
  // Only for -ις nouns: -α or -ιν
  const base = removeExistingAccentBreathing(lastGreekWord(word));
  const low = base.toLowerCase();
  if (!low.endsWith("ις")) return {form:"—", note:"Works best for feminine -ις nouns."};
  const stem = base.slice(0, -2);
  if (type === '-a'){
    return {form: nfc(stem + "ι" + "ν"), note:"(Toy) Many -ις feminines actually have acc. -ιν; use this button to compare forms."};
  }
  return {form: nfc(stem + "ιν"), note:"Accusative in -ιν (as in Herodian’s περισπώμενα examples)."};
}

// --- UI wiring ---
const examples = [
  "Κηφις",
  "Δελφις",
  "Κερκαφις",
  "Ακραιφις",
  "Ονουφις",
  "Μωμεμφις",
  "Παρεμφις",
  "παννυχις",
  "Τραχις",
  "Δουλιχις",
  "Ερυσιχις",
  "ραχις",
  "εχις",
  "Κολχις",
  "ρανις",
  "κρηπις",
  "Βενδις",
  "Αταργατις"
];

function getKind(){
  return ($$('input[name="kind"]').find(r=>r.checked) || {value:'auto'}).value;
}
function getAcc(){
  return ($$('input[name="acc"]').find(r=>r.checked) || {value:'auto'}).value;
}

function render(){
  const input = $('#inp').value;
  const kind = getKind();
  const acc = getAcc();
  const r = suggest(input, kind, acc);

  $('#norm').textContent = r.norm || '—';
  $('#ending').textContent = r.ending;
  $('#syll').textContent = String(r.syll);

  const kindBadge = `<span class="badge">kind: ${r.effectiveKind}</span>`;
  $('#accent').innerHTML = `<div class="mono" style="font-size:18px;margin-bottom:6px">${escapeHtml(r.suggestedForm)}</div>
    <div class="mini">${kindBadge} <span class="badge">${escapeHtml(r.label)}</span></div>
    <div class="mini">${escapeHtml(r.note)}</div>`;

  $('#accented').textContent = r.suggestedForm || '—';

  // accusative panel
  const low = stripAllCombining(r.norm).toLowerCase();
  if (low.endsWith('ις')){
    const a = makeAccusative(r.norm, '-a');
    const i = makeAccusative(r.norm, '-in');
    $('#accOut').textContent = `${a.form}  /  ${i.form}`;
    $('#accNote').textContent = 'Click a button to pick one and see the matching accent suggestion.';
  } else {
    $('#accOut').textContent = '—';
    $('#accNote').textContent = 'Accusative toy only triggers for words ending in -ις.';
  }
}

function escapeHtml(s){
  return (s??'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

$('#btnAnalyze').addEventListener('click', render);
$('#inp').addEventListener('input', () => { /* live */ render(); });

$('#btnRandom').addEventListener('click', () => {
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = ex;
  // reset toggles to auto for a clean demo
  $$('input[name="kind"]').forEach(r=>r.checked = (r.value==='auto'));
  $$('input[name="acc"]').forEach(r=>r.checked = (r.value==='auto'));
  render();
});

$('#btnClear').addEventListener('click', () => {
  $('#inp').value = '';
  render();
});

$$('input[name="kind"]').forEach(r => r.addEventListener('change', render));
$$('input[name="acc"]').forEach(r => r.addEventListener('change', render));

$('#btnOx').addEventListener('click', () => {
  const w = removeExistingAccentBreathing(lastGreekWord($('#inp').value));
  $('#accented').textContent = w ? addAccentToVowel(w, 1, 'acute') : '—';
});
$('#btnPro').addEventListener('click', () => {
  const w = removeExistingAccentBreathing(lastGreekWord($('#inp').value));
  $('#accented').textContent = w ? addAccentToVowel(w, 3, 'acute') : '—';
});
$('#btnPer').addEventListener('click', () => {
  const w = removeExistingAccentBreathing(lastGreekWord($('#inp').value));
  $('#accented').textContent = w ? addAccentToVowel(w, 1, 'circumflex') : '—';
});

$('#btnAccA').addEventListener('click', () => {
  // set acc toggle and re-render
  $$('input[name="acc"]').forEach(r=>r.checked = (r.value==='-a'));
  render();
});
$('#btnAccIn').addEventListener('click', () => {
  $$('input[name="acc"]').forEach(r=>r.checked = (r.value==='-in'));
  render();
});

// initial
render();

