const groups={final:'Final acute · oxytone',ante:'Antepenult acute · proparoxytone',bary:'Barytone · non-final accent',debate:'Qualified reading · accent and meaning'};
const rows=[];
function add(words,group,why,quote){for(const form of words.split(' '))rows.push({form,group,why,quote});}
add('νιφετός ὑετός κοπετός πυρετός τοκετός συρφετός','final','Listed examples of three-syllable appellatives or adjectives in -ετος. The rule is qualified: unless formed paronymously.','τρισύλλαβα … ὀξύνεται, εἰ μὴ παρωνύμως τετύπωται');
add('ἄσχετος ἄσπετος γνύπετος','ante','Explicit exceptions to the preceding final-acute pattern; γνύπετος is glossed ὁ χαῦνος, “the loose”.','τὸ μέντοι … προπαροξύνεται');
add('ἀμαιμάκετος περιμήκετος ἀριδείκετος ἐξαίρετος παλινάγρετος τηλύγετος Ταΰγετος ἀτρύγετος','ante','Cited in the longer -ετος series: more than three syllables, without a corresponding feminine formation, when used adjectivally. Keep these conditions with the rule.','ἐπιθετικῶς μὲν λαμβανόμενα τρίτην ἀπὸ τέλους');
add('λαιλαπετός','final','The passage gives final acute because this is not adjectival.','μὴ ὂν ἐπιθετικὸν ὠξύνθη');
add('Ἰαπετός','final','The passage cites this as a proper name with final acute.','Ἰαπετὸς ἐπὶ κυρίου');
add('Αἴνετος','ante','The opening contrasts this cited form with the adjective αἰνετός. Search αινετος to compare the two accents.','Αἴνετος, αἰνετὸς δὲ τὸ ἐπίθετον');
add('αἰνετός','final','Explicitly identified as the adjective, in contrast to Αἴνετος. The accent depends on which form is meant.','αἰνετὸς δὲ τὸ ἐπίθετον');
add('ἀφυσγετός','debate','Aristarchus: final acute if it is not adjectival. Tyrannion: a barytone reading entails construing it with something it modifies. The passage does not spell out an alternative accented form here.','εἴπερ οὐκ ἔστιν ἐπιθετικόν … κατὰ τὸν Ἀρίσταρχον · κατὰ τὸν Τυραννίωνα');
add('Ἄρητος Λάμητος Μέλητος βύνητος Μάσητος Μίλητος Κόρητος Κατάρητος Αἴνητος τρύγητος','bary','Cited under -τος proper names or adjectives with η in the penult and one gender. Barytone means non-final accent, not a mandatory written grave.','παραληγόμενα τῷ η μονογενῆ βαρύνονται');
add('ἀετός αἰετός','final','Both forms are explicitly said to have final acute in this passage.','ὀξύνεται καὶ ἀετὸς καὶ αἰετός');
function key(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/ς/g,'σ').trim();}
const word=document.querySelector('#word'),rule=document.querySelector('#rule'),out=document.querySelector('#results');
function node(tag,text,cls){const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e;}
function render(){
  const q=key(word.value),chosen=rule.value;
  const found=rows.filter(r=>(chosen==='all'||r.group===chosen)&&key(r.form).includes(q));
  out.replaceChildren();
  document.querySelector('#count').textContent=found.length+' passage example'+(found.length===1?'':'s')+(q?' matching your input':'');
  for(const r of found){const c=node('article','','card');const h=node('h2',r.form);h.lang='el';c.append(h,node('span',groups[r.group],'tag'),node('p',r.why));const quote=node('p',r.quote,'quote');quote.lang='el';c.append(quote);out.append(c);}
  if(!found.length)out.append(node('p','No cited example matches. Try a passage word or reset the filter; no accent is inferred for an unknown form.','empty'));
}
word.addEventListener('input',render);rule.addEventListener('change',render);
function load(value){word.value=value;rule.value='all';render();}
document.querySelector('#contrast').addEventListener('click',()=>load('αινετος'));
document.querySelector('#debate').addEventListener('click',()=>load('αφυσγετος'));
document.querySelector('#reset').addEventListener('click',()=>{load('');word.focus();});
render();

