const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const nfc=s=>s.normalize('NFC');
function key(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/σ$/,'ς');}
function lastGreekWord(s){const words=s.match(/[\p{Script=Greek}\p{M}]+/gu)||[];return words.at(-1)||'';}
function removeAccents(s){return nfc(s.normalize('NFD').replace(/[\u0300\u0301\u0342]/g,''));}
function clusters(word){const a=[];for(const ch of removeAccents(word).normalize('NFD')){if(/[\u0300-\u036f]/.test(ch)){if(a.length)a.at(-1).marks+=ch;}else a.push({ch,marks:''});}return a;}
function nuclei(letters){const out=[],diph=new Set(['αι','ει','οι','υι','αυ','ευ','ου','ηυ']);for(let i=0;i<letters.length;i++){if(!/[αεηιουω]/i.test(letters[i].ch))continue;const b=letters[i+1];if(b&&!b.marks.includes('\u0308')&&!letters[i].marks.includes('\u0308')&&diph.has((letters[i].ch+b.ch).toLowerCase())){out.push(i+1);i++;}else out.push(i);}return out;}
function roughSyllableCount(w){return nuclei(clusters(w)).length;}
function addAccent(word,fromEnd,type){const a=clusters(word),positions=nuclei(a);if(!positions.length)return removeAccents(word);const p=positions[Math.max(0,positions.length-fromEnd)];a[p].marks+=type==='circumflex'?'\u0342':'\u0301';return nfc(a.map(c=>c.ch+c.marks).join(''));}
function detectEnding(w){const k=key(w);return k.endsWith('φις')?'-φις':k.endsWith('χις')?'-χις':k.endsWith('ις')?'-ις':'(other)';}
const cited=new Map();
function list(forms,kind,label,note,acc=''){for(const form of forms.split(' '))cited.set(key(form),{form,kind,label,note,acc});}
list('Κηφίς Δελφίς ἀσταφίς κροταφίς ἐλαφίς Κερκαφίς Ἀκραιφίς','ethnic','oxytone (final acute)','Cited final-acute examples; Κηφίς, Δελφίς and Ἀκραιφίς are treated as ethnics.');
list('Ὄνουφις Μώμεμφις Πάρεμφις','proper','proparoxytone (antepenult acute)','Cited proper-name exceptions; preserve the passage’s spelling.');
list('Κολχίς Ἀντιοχίς παννυχίς Τραχίς Δουλιχίς Ἐρυσιχίς','ethnic','oxytone (final acute)','Cited final-acute spelling; place names require the individual evidence, not a blanket accent rule.');
list('ῥάχις ἔχις','exception','noted exception','Explicit exceptions to the -χις final-acute pattern.');
list('Ζοῦχις Τρῆχις Βῆχις Βῶγχις Ξοῦχις Ἀτάρβηχις Τεύωχις Ὕδελχις','city','place-name exception','A city or island example: retain its individually cited accent.');
list('ῥανίς κρηπίς κνημίς ἁψίς','feminine','oxytone (final acute)','Feminine, finally accented -ις nouns in the accusative -α class.','-a');
list('Βενδῖς Μολῖς Τοτῖς Ἀταργατῖς','feminine','perispomenon (final circumflex)','Feminine, finally accented -ις nouns in the accusative -ιν class.','-in');
const examples=Array.from(cited.values(),r=>r.form);
function getRadio(name){return $(`input[name="${name}"]:checked`).value;}
function resetRadios(){$$('input[name="kind"], input[name="acc"]').forEach(r=>r.checked=r.value==='auto');}
function suggest(input,kind,acc){
  const w=lastGreekWord(input),norm=removeAccents(w),ending=detectEnding(w),syll=roughSyllableCount(w),entry=cited.get(key(w));
  let form=norm,label='no passage rule applied',note='Try a cited example; unknown forms need grammatical information.',effectiveKind=kind;
  if(!w)return {w,norm:'',ending:'—',syll:0,form:'—',label:'No input',note:'Enter a Greek word to explore the passage.',effectiveKind:'—',entry:null};
  if(entry){form=entry.form;label=entry.label;note=entry.note;effectiveKind=entry.kind;if(kind!=='auto'&&kind!==entry.kind)note+=' The selected category does not override an attested spelling.';}
  else if(ending==='-φις'&&syll>2&&kind==='ethnic'){form=addAccent(w,1,'acute');label='conditional final acute';note='Applies to non-proper -φις words of more than two syllables. This input is not cited.';}
  else if(ending==='-χις'&&kind==='ethnic'){form=addAccent(w,1,'acute');label='conditional final acute';note='General -χις pattern, assuming this is not a place name or another exception. This input is not cited.';}
  else if(ending==='-ις'&&acc!=='auto'){form=addAccent(w,1,acc==='-in'?'circumflex':'acute');label=acc==='-in'?'conditional final circumflex':'conditional final acute';note='Assumes a feminine noun already accented on its final syllable. The ending alone does not establish this; the input is not cited.';}
  else if(ending==='-χις'&&kind==='city'){label='place-name evidence required';note='No single accent is supplied for all city/island names. Try Ζοῦχις or Ἀτάρβηχις.';}
  else if(ending==='-φις'&&kind==='proper'){label='proper-name evidence required';note='The general rule excludes proper names; it does not assign every proper name an antepenult acute. Try Ὄνουφις.';}
  return {w,norm,ending,syll,form,label,note,effectiveKind,entry};
}
function el(tag,text,cls){const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e;}
function render(){
  const acc=getRadio('acc'),r=suggest($('#inp').value,getRadio('kind'),acc);
  $('#norm').textContent=r.norm||'—';$('#ending').textContent=r.ending;$('#syll').textContent=r.w?String(r.syll):'—';
  const heading=el('div',r.form,'mono');heading.lang='el';heading.style.fontSize='18px';
  $('#accent').replaceChildren(heading,el('div',r.label,'badge'),el('p',r.note,'mini'));
  $('#accented').textContent=r.form;
  if(r.entry&&r.entry.acc){
    const actual=r.entry.acc==='-a'?'-α':'-ιν';
    $('#accOut').textContent='Cited class: '+actual;
    $('#accNote').textContent=acc==='auto'?'The passage gives this accusative class; full accusatives are not generated.':(acc===r.entry.acc?'Selected ending matches the cited class.':'Selected ending differs from the cited class. The passage’s nominative stays '+r.entry.form+'.');
  }else if(r.w&&r.ending==='-ις'){
    $('#accOut').textContent=acc==='auto'?'Choose -α or -ιν':acc==='-a'?'-α → final acute':'-ιν → final circumflex';
    $('#accNote').textContent='Conditional comparison only for feminine, finally accented -ις nouns. No full accusative is inferred.';
  }else{
    $('#accOut').textContent='—';$('#accNote').textContent=r.w?'This panel concerns the feminine -ις examples.':'Enter a Greek word first.';
  }
}
$('#btnAnalyze').addEventListener('click',render);$('#inp').addEventListener('input',render);
$('#btnRandom').addEventListener('click',()=>{$('#inp').value=examples[Math.floor(Math.random()*examples.length)];resetRadios();render();});
$('#btnClear').addEventListener('click',()=>{$('#inp').value='';resetRadios();render();$('#inp').focus();});
$$('input[name="kind"], input[name="acc"]').forEach(r=>r.addEventListener('change',render));
for(const [id,position,type] of [['btnOx',1,'acute'],['btnPro',3,'acute'],['btnPer',1,'circumflex']])$('#'+id).addEventListener('click',()=>{const w=lastGreekWord($('#inp').value);$('#accented').textContent=w?addAccent(w,position,type):'—';});
for(const [id,value] of [['btnAccA','-a'],['btnAccIn','-in']])$('#'+id).addEventListener('click',()=>{$$('input[name="acc"]').forEach(r=>r.checked=r.value===value);render();});
render();

original.gadget_css:
:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --panel2:#1d2136;
  --text:#e9ecff;
  --muted:#b9c0ff;
  --faint:#8b93d6;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#34d399;
  --warn:#fbbf24;
  --bad:#fb7185;
  --border:rgba(255,255,255,.10);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
}
*{box-sizing:border-box}
.wrap{max-width:980px;margin:18px auto;padding:14px;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,"Noto Sans",sans-serif;color:var(--text)}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1b1f3a 0%, var(--bg) 55%)}
.hdr{padding:14px 14px 6px}
.hdr h1{margin:0 0 6px;font-size:22px;letter-spacing:.2px}
.sub{margin:0;color:var(--muted);line-height:1.35}
.panel{background:linear-gradient(180deg,var(--panel),var(--panel2));border:1px solid var(--border);border-radius:14px;padding:14px;margin:12px 0;box-shadow:var(--shadow)}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.row.small{margin-top:10px;align-items:flex-start}
.lbl{min-width:70px;color:var(--muted);font-weight:600}
.inp{flex:1;min-width:260px;padding:10px 12px;border-radius:12px;border:1px solid var(--border);background:rgba(255,255,255,.06);color:var(--text);font-size:16px;outline:none}
.inp:focus{border-color:rgba(125,211,252,.55);box-shadow:0 0 0 4px rgba(125,211,252,.12)}
.btn{padding:9px 12px;border-radius:12px;border:1px solid rgba(125,211,252,.35);background:rgba(125,211,252,.12);color:var(--text);cursor:pointer;font-weight:650}
.btn:hover{background:rgba(125,211,252,.18)}
.btn:active{transform:translateY(1px)}
.btn.ghost{border-color:var(--border);background:rgba(255,255,255,.06);font-weight:600}
.btn.ghost:hover{background:rgba(255,255,255,.09)}
.tog{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:8px 10px;border:1px solid var(--border);border-radius:12px;background:rgba(255,255,255,.04)}
.lbl2{color:var(--muted);font-weight:650;margin-right:4px}
.tog label{color:var(--text);font-size:14px;display:flex;gap:6px;align-items:center}
.hint{color:var(--muted);line-height:1.35}
.hint ul{margin:8px 0 0 18px;padding:0}
.hint code{color:var(--accent);font-weight:700}
.out h2{margin:0 0 10px;font-size:18px}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
@media (max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}}
@media (max-width:520px){.grid{grid-template-columns:1fr}}
.card{border:1px solid var(--border);border-radius:12px;padding:10px;background:rgba(255,255,255,.04)}
.k{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.08em}
.v{margin-top:6px;font-size:15px}
.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono","Courier New",monospace}
.play{margin-top:12px}
.playRow{display:grid;grid-template-columns:1.3fr 1fr;gap:10px}
@media (max-width:900px){.playRow{grid-template-columns:1fr}}
.playCard{border:1px solid var(--border);border-radius:12px;padding:10px;background:rgba(255,255,255,.04)}
.btnRow{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0}
.big{font-size:22px;padding:10px 12px;border-radius:12px;border:1px dashed rgba(255,255,255,.18);background:rgba(0,0,0,.18)}
.mini{color:var(--faint);font-size:12.5px;margin-top:6px;line-height:1.25}
.details{margin-top:10px}
.details summary{cursor:pointer;color:var(--accent);font-weight:700}
.quote{margin-top:8px;padding:10px 12px;border-radius:12px;border:1px solid var(--border);background:rgba(0,0,0,.18);color:var(--muted);line-height:1.35}
.ftr{padding:4px 14px 14px}
.badge{display:inline-block;padding:2px 8px;border-radius:999px;border:1px solid var(--border);background:rgba(255,255,255,.05);color:var(--muted);font-size:12px}
.noteGood{color:var(--good);font-weight:700}
.noteWarn{color:var(--warn);font-weight:700}
.noteBad{color:var(--bad);font-weight:700}

original.gadget_js:
const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => Array.from(document.querySelectorAll(sel));

// --- Greek helpers (toy-level) ---
const COMBINING = {
  acute: "\u0301",
  circumflex: "\u0342",
  grave: "\u0300",
  diaeresis: "\u0308",
  smooth: "\u0313",
  rough: "\u0314",
  iotaSub: "\u0345"
};

function nfd(s){ return (s||"").normalize('NFD'); }
function nfc(s){ return (s||"").normalize('NFC'); }

function stripDiacriticsKeepDiaeresis(s){
  // Remove Greek accent/breathing/iota-subscript; keep diaeresis (useful for syllables).
  const t = nfd(s);
  let out = "";
  for (const ch of t){
    const code = ch.codePointAt(0);
    if (code >= 0x0300 && code <= 0x036F){
      if (ch === COMBINING.diaeresis) out += ch;
      // else drop
    } else out += ch;
  }
  return nfc(out);
}

function stripAllCombining(s){
  return nfc(nfd(s).replace(/[\u0300-\u036f]/g, ""));
}

function lastGreekWord(phrase){
  const s = (phrase||"").trim();
  if (!s) return "";
  // Keep Greek letters; split on whitespace/punct.
  const parts = s.split(/\s+/);
  return parts[parts.length-1].replace(/^[^\p{L}]+|[^\p{L}]+$/gu, "");
}

const VOWELS = new Set(["α","ε","η","ι","ο","υ","ω","ά","έ","ή","ί","ό","ύ","ώ","ϊ","ϋ","ΐ","ΰ",
                        "Α","Ε","Η","Ι","Ο","Υ","Ω","Ά","Έ","Ή","Ί","Ό","Ύ","Ώ","Ϊ","Ϋ"]);

function isVowelChar(ch){
  return VOWELS.has(ch);
}

function roughSyllableCount(word){
  // Very rough: count vowel nuclei (including diphthongs as 1 unless diaeresis splits).
  const w = stripDiacriticsKeepDiaeresis(word);
  const s = nfd(w);
  // Build array of base letters with possible diaeresis marker.
  const letters = [];
  let cur = null;
  for (const ch of s){
    if (ch.match(/[\u0300-\u036f]/)){
      if (cur && ch === COMBINING.diaeresis) cur.dia = true;
    } else {
      cur = {ch, dia:false};
      letters.push(cur);
    }
  }
  let count = 0;
  for (let i=0;i<letters.length;i++){
    const a = letters[i];
    if (!isVowelChar(a.ch)) continue;
    // diphthong check with next vowel
    const b = letters[i+1];
    if (b && isVowelChar(b.ch) && !b.dia && !a.dia){
      const pair = (a.ch + b.ch).toLowerCase();
      const diph = new Set(["αι","ει","οι","υι","αυ","ευ","ου","ηυ","ωυ"]);
      if (diph.has(pair)){
        count += 1;
        i += 1;
        continue;
      }
    }
    count += 1;
  }
  return Math.max(count, 1);
}

function detectEnding(word){
  const w = stripAllCombining(word).toLowerCase();
  if (w.endsWith("φις")) return "-φις";
  if (w.endsWith("χις")) return "-χις";
  if (w.endsWith("ις")) return "-ις";
  return "(other)";
}

function removeExistingAccentBreathing(word){
  // remove all combining marks; keep base letters
  return stripAllCombining(word);
}

function addAccentToVowel(word, vowelIndexFromEnd, accentType){
  // accentType: 'acute' | 'circumflex'
  // vowelIndexFromEnd: 1=last vowel nucleus, 2=penult nucleus, 3=antepenult nucleus
  const base = removeExistingAccentBreathing(word);
  const letters = Array.from(nfd(base));
  // Find vowel positions (indices in letters array) for nuclei (approx: each vowel letter counts)
  const vowelPositions = [];
  for (let i=0;i<letters.length;i++){
    const ch = letters[i];
    if (ch.match(/[\u0300-\u036f]/)) continue;
    if (isVowelChar(ch)) vowelPositions.push(i);
  }
  if (!vowelPositions.length) return base;
  const pos = vowelPositions[Math.max(0, vowelPositions.length - vowelIndexFromEnd)];
  const mark = accentType === 'circumflex' ? COMBINING.circumflex : COMBINING.acute;
  letters[pos] = letters[pos] + mark;
  return nfc(letters.join(""));
}

function suggest(word, kind, accChoice){
  const w = lastGreekWord(word);
  const norm = removeExistingAccentBreathing(w);
  const ending = detectEnding(w);
  const syll = roughSyllableCount(w);

  let note = "";
  let suggestedForm = norm;
  let label = "";

  // Auto heuristics: if ends with -ουφις or -εμφις treat as proper-ish (based on examples)
  const low = stripAllCombining(w).toLowerCase();
  const autoProper = /ουφις$/.test(low) || /εμφις$/.test(low);

  const effectiveKind = (kind === 'auto') ? (autoProper ? 'proper' : 'ethnic') : kind;

  if (ending === "-φις"){
    if (effectiveKind === 'proper'){
      suggestedForm = addAccentToVowel(norm, 3, 'acute');
      label = "proparoxytone (antepenult acute)";
      note = "Toy rule: proper names in -φις often προπαροξύνονται (e.g. Ὄνουφις, Μώμεμφις).";
    } else {
      if (syll > 2){
        suggestedForm = addAccentToVowel(norm, 1, 'acute');
        label = "oxytone (final acute)";
        note = "Toy rule: -φις with >2 syllables tends to be oxytone (ὀξύνεται).";
      } else {
        suggestedForm = addAccentToVowel(norm, 1, 'acute');
        label = "oxytone (final acute)";
        note = "Short -φις: this toy still makes it oxytone (cf. Κηφίς, Δελφίς).";
      }
    }
  } else if (ending === "-χις"){
    if (effectiveKind === 'city'){
      suggestedForm = addAccentToVowel(norm, 1, 'acute');
      label = "(place-name exception flagged)";
      note = "Herodian notes place-name exceptions for -χις; this toy keeps final acute but flags it.";
    } else {
      suggestedForm = addAccentToVowel(norm, 1, 'acute');
      label = "oxytone (final acute)";
      note = "Toy rule: -χις tends to be oxytone (ὀξύνεται).";
    }
  } else if (ending === "-ις"){
    // Feminine -is rule based on accusative
    let acc = accChoice;
    if (acc === 'auto'){
      // guess: if ends with -δις/-τις etc maybe -ιν? too hard; default to -α
      acc = '-a';
    }
    if (acc === '-a'){
      suggestedForm = addAccentToVowel(norm, 1, 'acute');
      label = "oxytone (final acute)";
      note = "If acc. is -α, Herodian: ὀξύνονται (e.g. ῥανίς).";
    } else {
      suggestedForm = addAccentToVowel(norm, 1, 'circumflex');
      label = "perispomenon (final circumflex)";
      note = "If acc. is -ιν, Herodian: περισπῶνται (e.g. Βενδῖς).";
    }
  } else {
    suggestedForm = norm;
    label = "(no rule applied)";
    note = "Try a word ending in -φις, -χις, or -ις.";
  }

  return {w, norm, ending, syll, effectiveKind, suggestedForm, label, note};
}

function makeAccusative(word, type){
  // Only for -ις nouns: -α or -ιν
  const base = removeExistingAccentBreathing(lastGreekWord(word));
  const low = base.toLowerCase();
  if (!low.endsWith("ις")) return {form:"—", note:"Works best for feminine -ις nouns."};
  const stem = base.slice(0, -2);
  if (type === '-a'){
    return {form: nfc(stem + "ι" + "ν"), note:"(Toy) Many -ις feminines actually have acc. -ιν; use this button to compare forms."};
  }
  return {form: nfc(stem + "ιν"), note:"Accusative in -ιν (as in Herodian’s περισπώμενα examples)."};
}

// --- UI wiring ---
const examples = [
  "Κηφις",
  "Δελφις",
  "Κερκαφις",
  "Ακραιφις",
  "Ονουφις",
  "Μωμεμφις",
  "Παρεμφις",
  "παννυχις",
  "Τραχις",
  "Δουλιχις",
  "Ερυσιχις",
  "ραχις",
  "εχις",
  "Κολχις",
  "ρανις",
  "κρηπις",
  "Βενδις",
  "Αταργατις"
];

function getKind(){
  return ($$('input[name="kind"]').find(r=>r.checked) || {value:'auto'}).value;
}
function getAcc(){
  return ($$('input[name="acc"]').find(r=>r.checked) || {value:'auto'}).value;
}

function render(){
  const input = $('#inp').value;
  const kind = getKind();
  const acc = getAcc();
  const r = suggest(input, kind, acc);

  $('#norm').textContent = r.norm || '—';
  $('#ending').textContent = r.ending;
  $('#syll').textContent = String(r.syll);

  const kindBadge = `<span class="badge">kind: ${r.effectiveKind}</span>`;
  $('#accent').innerHTML = `<div class="mono" style="font-size:18px;margin-bottom:6px">${escapeHtml(r.suggestedForm)}</div>
    <div class="mini">${kindBadge} <span class="badge">${escapeHtml(r.label)}</span></div>
    <div class="mini">${escapeHtml(r.note)}</div>`;

  $('#accented').textContent = r.suggestedForm || '—';

  // accusative panel
  const low = stripAllCombining(r.norm).toLowerCase();
  if (low.endsWith('ις')){
    const a = makeAccusative(r.norm, '-a');
    const i = makeAccusative(r.norm, '-in');
    $('#accOut').textContent = `${a.form}  /  ${i.form}`;
    $('#accNote').textContent = 'Click a button to pick one and see the matching accent suggestion.';
  } else {
    $('#accOut').textContent = '—';
    $('#accNote').textContent = 'Accusative toy only triggers for words ending in -ις.';
  }
}

function escapeHtml(s){
  return (s??'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

$('#btnAnalyze').addEventListener('click', render);
$('#inp').addEventListener('input', () => { /* live */ render(); });

$('#btnRandom').addEventListener('click', () => {
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = ex;
  // reset toggles to auto for a clean demo
  $$('input[name="kind"]').forEach(r=>r.checked = (r.value==='auto'));
  $$('input[name="acc"]').forEach(r=>r.checked = (r.value==='auto'));
  render();
});

$('#btnClear').addEventListener('click', () => {
  $('#inp').value = '';
  render();
});

$$('input[name="kind"]').forEach(r => r.addEventListener('change', render));
$$('input[name="acc"]').forEach(r => r.addEventListener('change', render));

$('#btnOx').addEventListener('click', () => {
  const w = removeExistingAccentBreathing(lastGreekWord($('#inp').value));
  $('#accented').textContent = w ? addAccentToVowel(w, 1, 'acute') : '—';
});
$('#btnPro').addEventListener('click', () => {
  const w = removeExistingAccentBreathing(lastGreekWord($('#inp').value));
  $('#accented').textContent = w ? addAccentToVowel(w, 3, 'acute') : '—';
});
$('#btnPer').addEventListener('click', () => {
  const w = removeExistingAccentBreathing(lastGreekWord($('#inp').value));
  $('#accented').textContent = w ? addAccentToVowel(w, 1, 'circumflex') : '—';
});

$('#btnAccA').addEventListener('click', () => {
  // set acc toggle and re-render
  $$('input[name="acc"]').forEach(r=>r.checked = (r.value==='-a'));
  render();
});
$('#btnAccIn').addEventListener('click', () => {
  $$('input[name="acc"]').forEach(r=>r.checked = (r.value==='-in'));
  render();
});

// initial
render();
